const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-63.1811, -17.7833]); // Santa Cruz de la Sierra coordinates
  const buffer = point.buffer(50000); // 50km buffer for eastern region
  const geometry = buffer;

  const start1986 = '1986-08-01';
  const end1986 = '1986-08-31';
  const start2001 = '2001-08-01';
  const end2001 = '2001-08-31';

  // 2. Data Acquisition - Landsat 5 for both periods
  const getLandsat5 = (startDate, endDate) => {
    return ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
      .filterDate(startDate, endDate)
      .filterBounds(geometry)
      .filter(ee.Filter.lt('CLOUD_COVER', 20));
  };

  const col1986 = getLandsat5(start1986, end1986);
  const col2001 = getLandsat5(start2001, end2001);

  // Check collection sizes
  const size1986 = col1986.size().getInfo();
  const size2001 = col2001.size().getInfo();

  // Handle empty collections by widening date range
  if (size1986 === 0) {
    const col1986Wide = getLandsat5('1986-07-15', '1986-09-15');
    const size1986Wide = col1986Wide.size().getInfo();
    if (size1986Wide === 0) {
      console.log("1986 Images: 0");
      console.log("<answer>C1</answer>");
      return;
    }
    // Use median of wider collection
    const img1986 = col1986Wide.median();
    console.log(`1986 Images: 0 -> ${size1986Wide} (widened period)`);
  } else {
    const img1986 = col1986.median();
    console.log(`1986 Images: ${size1986}`);
  }

  if (size2001 === 0) {
    const col2001Wide = getLandsat5('2001-07-15', '2001-09-15');
    const size2001Wide = col2001Wide.size().getInfo();
    if (size2001Wide === 0) {
      console.log("2001 Images: 0");
      console.log("<answer>C1</answer>");
      return;
    }
    // Use median of wider collection
    const img2001 = col2001Wide.median();
    console.log(`2001 Images: 0 -> ${size2001Wide} (widened period)`);
  } else {
    const img2001 = col2001.median();
    console.log(`2001 Images: ${size2001}`);
  }

  // 3. Processing - Calculate NDVI for forest cover
  const getNDVI = (img) => {
    // Cloud masking using QA band
    const cloudMask = img.select('pixel_qa').bitwiseAnd(32).eq(0);
    const imgMasked = img.updateMask(cloudMask);

    // Calculate NDVI: (NIR - Red) / (NIR + Red)
    // Bands: B4 = Red, B5 = NIR
    const ndvi = imgMasked.normalizedDifference(['B5', 'B4']).rename('NDVI');
    return ndvi;
  };

  const ndvi1986 = getNDVI(col1986.size() > 0 ? col1986.median() : col1986Wide.median());
  const ndvi2001 = getNDVI(col2001.size() > 0 ? col2001.median() : col2001Wide.median());

  // 4. Calculation - Get mean NDVI values
  const getMeanNDVI = (ndviImg) => {
    const stats = ndviImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9,
    });
    return stats.get('NDVI').getInfo();
  };

  const mean1986 = getMeanNDVI(ndvi1986);
  const mean2001 = getMeanNDVI(ndvi2001);

  // Check for valid pixels
  if (mean1986 === null || mean2001 === null) {
    console.log("No valid pixels after masking");
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Validation & Final Answer
  console.log(`1986 Mean NDVI: ${mean1986?.toFixed(4) ?? 'null'}`);
  console.log(`2001 Mean NDVI: ${mean2001?.toFixed(4) ?? 'null'}`);

  // Check if calculation failed
  if (mean1986 === undefined || mean2001 === undefined || 
      isNaN(mean1986) || isNaN(mean2001)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Forest cover decreased if NDVI2001 < NDVI1986 (with threshold for small changes)
  const threshold = 0.02; // 2% threshold for meaningful change
  const change = mean2001 - mean1986;

  if (change < -threshold) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
